import json, sys, os
from datetime import datetime, timezone

# Read current memory files
def parse_memory_entries(filepath, source_type):
    with open(filepath) as f:
        content = f.read()
    entries = content.split('\n§\n')
    results = []
    for i, entry in enumerate(entries):
        entry = entry.strip()
        if entry:
            results.append({
                'source': source_type,
                'index': i,
                'content': entry,
                'timestamp': datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
            })
    return results

mem_entries = parse_memory_entries(os.path.expanduser('~/.hermes/memories/MEMORY.md'), 'memory')
user_entries = parse_memory_entries(os.path.expanduser('~/.hermes/memories/USER.md'), 'user_profile')

all_entries = mem_entries + user_entries
print(f'Found {len(all_entries)} entries to process ({len(mem_entries)} memory + {len(user_entries)} user profile)')
print()

# Process each through MemPalace capture system
sys.path.insert(0, os.path.expanduser('~/.hermes/mempalace'))

# Try to import capture module
try:
    from capture import capture_event
    capture_ok = True
except ImportError as e:
    print(f'⚠️ Could not import capture module: {e}')
    capture_ok = False

try:
    from tag import extract_context_tags
    tag_ok = True
except ImportError:
    tag_ok = False

for i, entry in enumerate(all_entries):
    print(f'  [{i+1}/{len(all_entries)}] {entry[\"source\"]}: {entry[\"content\"][:60]}...')

    if capture_ok:
        try:
            result = capture_event({
                'type': 'memory_dump' if entry['source'] == 'memory' else 'user_profile',
                'content': entry['content'],
                'context': f'memory-consolidation, {entry[\"source\"]}',
                'timestamp': entry['timestamp'],
                'source': f'hermes-{entry[\"source\"]}'
            })
            print(f'    ✓ Captured to raw store')
        except Exception as e:
            print(f'    ✗ Capture error: {e}')

    if tag_ok and 'extract_context_tags' in dir():
        try:
            tags = extract_context_tags(entry['content'])
            print(f'    Tags: {tags[:3]}...')
        except:
            pass

print()
print('Done. Now run consolidation...')
